package com.portfoliv.app;
import android.content.Context;import android.security.keystore.*;import android.util.AtomicFile;import java.io.*;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.nio.charset.StandardCharsets;
final class StateStore {
 private final AtomicFile file;
 StateStore(Context context){file=new AtomicFile(new File(context.getNoBackupFilesDir(),"work-state.enc"));}
 private javax.crypto.SecretKey key() throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="portfoliv.work.v2";if(!store.containsAlias(alias)){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (javax.crypto.SecretKey)store.getKey(alias,null);}
 synchronized String read(){try{byte[] data=file.readFully();if(data.length<28)return "null";Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,data,0,12));cipher.updateAAD("portfoliv-state-v2".getBytes(StandardCharsets.UTF_8));return new String(cipher.doFinal(data,12,data.length-12),StandardCharsets.UTF_8);}catch(Exception e){return "null";}}
 synchronized void write(String value) throws Exception {if(value==null||value.length()>7500000)throw new IOException();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD("portfoliv-state-v2".getBytes(StandardCharsets.UTF_8));byte[] bytes=cipher.doFinal(value.getBytes(StandardCharsets.UTF_8));FileOutputStream out=null;try{out=file.startWrite();out.write(cipher.getIV());out.write(bytes);file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
}
